create table if not exists public.marketer_profile_deep_research (id uuid primary key default gen_random_uuid(), applicant_id uuid not null references public.users(id) on delete cascade, profile_url text not null, platform text not null, status text not null default 'completed', research jsonb not null default '{}'::jsonb, requested_by uuid references public.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.users add column if not exists marketer_deep_research jsonb not null default '[]'::jsonb; alter table public.marketer_profile_deep_research enable row level security;